// =============================================================
// EK QUIZ SORULARI (iki dilli) — politika dosyalarındaki doğrulanmış olgulardan
// Yazım kolaylığı için kısa bir yardımcı fonksiyon kullanılır:
//   S(konu, dogru, [soruTR, soruEN], [seçeneklerTR], [seçeneklerEN], [açıklamaTR, açıklamaEN])
// dogru: doğru seçeneğin sırası (0 = A)
// =============================================================

Object.assign(KONULAR, {
  karadeniz: { tr: "Karadeniz ve Montrö", en: "Black Sea and Montreux" },
  iran: { tr: "İran ve Körfez", en: "Iran and the Gulf" },
  afrika: { tr: "Afrika", en: "Africa" },
  enerji: { tr: "Enerji ve İklim", en: "Energy and Climate" },
  hukuk: { tr: "Diplomatik ve Konsolosluk Hukuku", en: "Diplomatic and Consular Law" }
});

function S(konu, dogru, soru, secTr, secEn, ac) {
  return { konu, dogru, soru: { tr: soru[0], en: soru[1] }, secenekler: { tr: secTr, en: secEn }, aciklama: { tr: ac[0], en: ac[1] } };
}

